mapper.select:
SELECT COUNT(DISTINCT payment.order_id)
FROM payments AS payment
WHERE payment.status = 'DONE'
  AND payment.approved_at >= #{start}
  AND payment.approved_at < #{end}

SELECT COALESCE(SUM(payment.amount), 0)
FROM payments AS payment
WHERE payment.status = 'DONE'
  AND payment.approved_at >= #{start}
  AND payment.approved_at < #{end}

SELECT COUNT(*)
FROM orders AS pickup_order
WHERE pickup_order.pickup_at >= #{start}
  AND pickup_order.pickup_at < #{end}
  AND pickup_order.status = 'READY_FOR_PICKUP'
